60:   void trackWindowSize(QResizeEvent * event)
61:   {
62:     this->windowsize = SbVec2s(event->size().width(),
63:                                event->size().height());
64: 
65:     foreach(InputDevice * device, this->devices) {
66:       device->setWindowSize(this->windowsize);
67:     }
