71:   {
72:     assert(this->windowsize[1] != -1);
73: #if QT_VERSION >= 0x060000
74:     this->globalmousepos = event->globalPosition().toPoint();
75: #else
76:     this->globalmousepos = event->globalPos();
77: #endif
78: 
79:     SbVec2s mousepos(event->pos().x(), this->windowsize[1] - event->pos().y() - 1);
80:     // the following corrects for high-dpi displays (e.g., mac retina)
81:     mousepos *= quarterwidget->devicePixelRatio();
82:     foreach(InputDevice * device, this->devices) {
83:       device->setMousePosition(mousepos);
84:     }
85:   }
86: 
