144: /*! Translates Qt Events into Coin events and passes them on to the
145:   event QuarterWidget for processing. If the event cannot be
146:   translated or processed, it is forwarded to Qt and the method
147:   returns false.
148:  */
149: bool
150: EventFilter::eventFilter(QObject * obj, QEvent * qevent)
151: {
152:   // make sure every device has updated screen size and mouse position
153:   // before translating events
154:   switch (qevent->type()) {
155:   case QEvent::MouseMove:
156:   case QEvent::MouseButtonPress:
157:   case QEvent::MouseButtonRelease:
158:   case QEvent::MouseButtonDblClick:
159:     PRIVATE(this)->trackPointerPosition(dynamic_cast<QMouseEvent *>(qevent));
160:     break;
161:   case QEvent::Resize:
162:     PRIVATE(this)->trackWindowSize(dynamic_cast<QResizeEvent *>(qevent));
163:     break;
164:   default:
165:     break;
166:   }
167: 
168:   // translate QEvent into SoEvent and see if it is handled by scene
169:   // graph
170:   foreach(InputDevice * device, PRIVATE(this)->devices) {
171:     const SoEvent * soevent = device->translateEvent(qevent);
172:     if (soevent && PRIVATE(this)->quarterwidget->processSoEvent(soevent)) {
173:       return true;
174:     }
175:   }
176:   return false;
177: }
