#include "SignalThread.h"

using namespace SIM::Coin3D::Quarter;

SignalThread::SignalThread(void)
  : isstopped(false)
{
}

SignalThread::~SignalThread()
{
}

void
SignalThread::trigger(void)
{
  // lock first to make sure the QThread is actually waiting for a signal
  this->mutex.lock();
  this->waitcond.wakeOne();
  this->mutex.unlock();
}

void
SignalThread::stopThread(void)
{
  this->mutex.lock();
  this->isstopped = true;
  this->waitcond.wakeOne();
  this->mutex.unlock();
}


void
SignalThread::run(void)
{
  this->mutex.lock();
  while (!this->isstopped) {
    // just wait, and trigger every time we receive a signal
    this->waitcond.wait(&this->mutex);
    if (!this->isstopped) {
      emit triggerSignal();
    }
  }
  this->mutex.unlock();
}","lineStart":1,"lineEnd":77,"totalLines":77,"truncated":false}},"title":"repos/ruangong-0707/quarter/src/Quarter/SignalThread.cpp","time":{"start":1783496863925,"end":1783496863931}},"id":"prt_f40b26d2c001Uw2SDZD7XpKFQ0","sessionID":"ses_0bf55d5beffegCXyTOzd4RNGZV","messageID":"msg_f40b24d07001SQzDy6LYH8OD1U"}}

